#!/usr/bin/env python3
"""Готовит tools/data.json для раздаточного листа: условия задач (текст с acmp.ru, взят из комментариев
к решениям в репозитории github.com/shohrukh92/acmp), примеры (ответы считает эталонное решение), код решений."""
import inspect, json, sys, os
sys.path.insert(0, os.path.dirname(__file__))
from solutions import SOLVE

